    h,w=len(g),len(g[0])
    # separator rows/cols are full of the frame color
    sr=[i for i,r in enumerate(grid) if len(set(r))==1 and r[0]!=0]
    sc=[j for j in range(w) if len({grid[i][j] for i in range(h)})==1 and grid[0][j]!=0]
    frame=grid[sr[0]][0] if sr else grid[0][sc[0]]
    rb=[]; last=-1
    for x in sr+[h]:
        if x-last>1: rb.append((last+1,x))
        last=x
    cb=[]; last=-1
    for x in sc+[w]:
        if x-last>1: cb.append((last+1,x))
        last=x
    # union of nonzero/non-frame object coordinates, assumed object color
    pts=set()
    for a,b in rb:
      for c,d in cb:
        for i in range(a,b):
          for j in range(c,d):
            if grid[i][j] not in (0,frame): pts.add((i-a,j-c))
    for a,b in rb:
      for c,d in cb:
        for di,dj in pts:
          i,j=a+di,c+dj
          if a<=i<b and c<=j<d and g[i][j]==0: g[i][j]=frame
